// Elasticsearch index mapping
var createIndexResponse = await _client.Indices.CreateAsync("products", c => c
    .Map<ProductDocument>(m => m
        .AutoMap()
        .Properties(p => p
            .Text(t => t
                .Name(n => n.Name)
                .Analyzer("standard")
            )
            .Keyword(k => k.Name(n => n.Category))
        )
    )
);
